#!/bin/bash
# Evaluate deploy/cyrus/alert-rules.json once and post changes to Discord. docs/CYRUS-PLATFORM.md section 5.
#   scripts/cyrus/alert-check.sh [--dry-run] [--rules FILE]
# Env: CYRUS_ALERT_DISCORD_WEBHOOK (no webhook = print only), CYRUS_HEALTH_URL, CYRUS_DATABASE_URL or DATABASE_URL
# (read-only queries), CYRUS_BACKUP_TARGET (as backup-nightly.sh), CYRUS_SPEND_ALERT_USD, CYRUS_ALERT_STATE (state
# file for consecutive counts / repeat suppression, default /var/lib/cyrus/alert-state.json).
set -euo pipefail
ROOT="$(cd "$(dirname "$(readlink -f "$0")")/../.." && pwd)"
DRY=0; RULES="$ROOT/deploy/cyrus/alert-rules.json"
while [ $# -gt 0 ]; do case "$1" in --dry-run) DRY=1 ;; --rules) RULES="$2"; shift ;; *) exit 2 ;; esac; shift; done
export CYRUS_HEALTH_URL="${CYRUS_HEALTH_URL:-http://127.0.0.1:3000/api/cyrus/health}"
export CYRUS_ALERT_STATE="${CYRUS_ALERT_STATE:-/var/lib/cyrus/alert-state.json}" DRY RULES
exec node - <<'JS'
const fs = require("fs"), { execFileSync } = require("child_process");
const env = process.env, dry = env.DRY === "1";
const expand = (s) => s.replace(/\$\{(\w+)(?::-([^}]*))?\}/g, (_, k, d) => env[k] ?? d ?? "");
const rules = JSON.parse(fs.readFileSync(env.RULES, "utf8")).rules;
let state = {}; try { state = JSON.parse(fs.readFileSync(env.CYRUS_ALERT_STATE, "utf8")); } catch {}
const db = (env.CYRUS_DATABASE_URL || env.DATABASE_URL || "").replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace("?&", "?").replace(/[?&]+$/, "");
const sql = (q) => execFileSync("psql", [db, "-XAtq", "-v", "ON_ERROR_STOP=1", "-c", q], { encoding: "utf8", timeout: 20000 }).trim();
const curl = (u) => { try { return execFileSync("curl", ["-s", "--max-time", "10", "-w", "\n%{http_code}", u], { encoding: "utf8" }); } catch { return "\n000"; } };
function evaluate(r) { // -> problem text, or "" when fine
  if (r.kind === "http") { const code = curl(expand(r.url)).split("\n").pop(); return code === String(r.expect) ? "" : `HTTP ${code} from ${expand(r.url)}`; }
  if (r.kind === "http-json") { const out = curl(expand(r.url)).split("\n"); out.pop(); try { const v = JSON.parse(out.join("\n"))[r.field]; return v === r.notEquals ? `${r.field}=${v}` : ""; } catch { return ""; } }
  if (r.kind === "backup-age") {
    const t = env.CYRUS_BACKUP_TARGET || "root@178.63.94.114:/tank/cyrus-backups"; const [h, d] = t.includes(":") ? t.split(/:(.*)/) : [null, t];
    let last = ""; try { last = h ? execFileSync("ssh", ["-o", "BatchMode=yes", h, `cat '${d}/LAST_SUCCESS'`], { encoding: "utf8", timeout: 20000 }).trim() : fs.readFileSync(`${d}/LAST_SUCCESS`, "utf8").trim(); } catch {}
    const age = last ? (Date.now() - Date.parse(last)) / 3.6e6 : Infinity; return age > r.maxHours ? (last ? `last backup ${age.toFixed(1)} h ago` : "no successful backup recorded") : "";
  }
  // r51: a disk or pool above its threshold (df -P, locally or on node-2 over ssh; read only)
  if (r.kind === "disk") {
    const host = r.host ? expand(r.host) : "";
    const out = host ? execFileSync("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, `df -P '${r.path}'`], { encoding: "utf8", timeout: 20000 }) : execFileSync("df", ["-P", r.path], { encoding: "utf8", timeout: 20000 });
    const pct = Number((out.trim().split("\n").pop() || "").split(/\s+/)[4]?.replace("%", ""));
    const where = `${host ? "node-2 " : ""}${r.path}`;
    return pct >= (r.critPct ?? 90) ? `${where} is ${pct}% full (critical at ${r.critPct ?? 90}%)` : pct >= (r.warnPct ?? 80) ? `${where} is ${pct}% full (warning at ${r.warnPct ?? 80}%)` : "";
  }
  if (r.kind === "sql") {
    if (!db) return "";
    if (r.optionalTable && sql(`select to_regclass('public."${r.optionalTable}"') is null`) === "t") return "";
    return sql(expand(r.sql));
  }
  return "";
}
const posts = []; const now = Date.now();
for (const r of rules) {
  let problem = ""; try { problem = evaluate(r); } catch (e) { problem = `check error: ${String(e.message).split("\n")[0].slice(0, 160)}`; }
  const s = (state[r.id] ??= { fails: 0, firing: false, lastPost: 0 });
  if (problem) {
    s.fails++;
    if (s.fails >= (r.consecutive ?? 1) && (!s.firing || now - s.lastPost > (r.repeatMin ?? 60) * 60000)) { s.firing = true; s.lastPost = now; posts.push(`${r.severity === "critical" ? "CRITICAL" : "WARN"} cyrus/${r.id}: ${problem}`); }
  } else {
    if (s.firing) posts.push(`RESOLVED cyrus/${r.id}`);
    Object.assign(s, { fails: 0, firing: false });
  }
  console.log(`${problem ? "FAIL" : "ok  "} ${r.id}${problem ? ": " + problem : ""}`);
}
if (!dry) { try { fs.mkdirSync(require("path").dirname(env.CYRUS_ALERT_STATE), { recursive: true }); fs.writeFileSync(env.CYRUS_ALERT_STATE, JSON.stringify(state)); } catch (e) { console.error("state not saved:", e.message); } }
for (const p of posts) {
  console.log(`alert: ${p}`);
  if (dry || !env.CYRUS_ALERT_DISCORD_WEBHOOK) continue;
  try { execFileSync("curl", ["-s", "--max-time", "10", "-H", "content-type: application/json", "-d", JSON.stringify({ content: p.slice(0, 1900), allowed_mentions: { parse: [] } }), env.CYRUS_ALERT_DISCORD_WEBHOOK]); } catch {}
}
