    { "id": "webhook-dead-letters", "kind": "sql", "optionalTable": "CyrusWebhookOutbox", "sql": "select case when count(*) > 0 then count(*) || ' webhook deliveries in dead letter' end from \"CyrusWebhookOutbox\" where status = 'dead'", "severity": "warning", "repeatMin": 240 }
