input.content:
// Cyrus launch check: PURE evaluation. facts (collected read-only by launch-check.mjs) -> rows + verdicts.
// No I/O, no clock (facts.now), no secrets: unit-tested in test/cyrus-launch-check.test.ts and
// re-used by the admin Launch tab (lib/cyrus/admin/readiness.ts only parses the JSON this produces).
//
// Every row carries two statuses: `beta` (private beta: owner + allow-listed accounts) and `public`
// (anyone can sign up and pay). PASS / WARN / FAIL / INFO (never counted) / SKIP (not applicable).
// Verdict per audience: any FAIL = NO-GO, otherwise GO (warnings are listed, not blocking).

export const LAUNCH_SCHEMA = "cyrus-launch-check-1";
export const DAY = 86_400_000;

// Thresholds. PLACEHOLDER pending the owner: starting points, not measurements.
export const THRESHOLDS = {
  diskWarnPct: 80, diskFailPct: 90,
  certWarnDays: 21, certFailDays: 7,
  backupWarnHours: 30, backupFailHours: 72,
  guardWarnDays: 7,
  evalWarnDays: 14, evalFailDays: 30,
  evalMinFinalPassPct: 90, evalMinPassAt1Pct: 40,
  queueWarn: 10,
};

// First path segments the Cyrus host serves through the app (lib/cyrus/bridge/routing.ts; guarded by the test).
export const REQUIRED_APP_PREFIXES = ["studio", "home", "new", "account", "assets", "servers", "wallet", "projects", "help", "plans", "sign-in", "sign-up", "auth", "login", "register", "api/cyrus", "api/mod-builder", "api/nxlabs/cyrus", "api/log", "legal", "_next", "vendor"];

const S = { PASS: "PASS", WARN: "WARN", FAIL: "FAIL", INFO: "INFO", SKIP: "SKIP" };
const ORDER = ["FAIL", "WARN", "PASS", "INFO", "SKIP"];

/** A row. `pub` overrides the public-launch status when it differs from beta (default: same as beta). */
const row = (id, area, title, status, detail, action = "", pub = null) => ({ id, area, title, beta: status, public: pub ?? status, detail, action });
/** Something only a PUBLIC launch needs: FAIL/WARN for public, WARN/INFO for beta. */
const publicOnly = (id, area, title, status, detail, action = "") =>
  row(id, area, title, status === S.FAIL ? S.WARN : status === S.WARN ? S.INFO : status, detail, action, status);

const ageMs = (iso, now) => { const t = Date.parse(iso || ""); return Number.isFinite(t) ? Date.parse(now) - t : null; };
const hours = (ms) => Math.round(ms / 3.6e5 * 10) / 10;
const days = (ms) => Math.round(ms / DAY * 10) / 10;
const truthy = (v) => v === "1" || v === "true" || v === true;
const unit = (v) => (v === undefined || v === null || v === "" ? "unset" : String(v));

export function evaluate(f, T = THRESHOLDS) {
  const rows = [];
  const add = (r) => rows.push(r);
  const set = f.settings || {};
  const env = f.env || {};
  const pair = { pub: truthy(set.cyrus_studio_public_enabled), tok: truthy(set.cyrus_tok_live) };
  const isPublic = pair.pub && pair.tok;

  // ---- build service
  const svc = f.svc;
  if (!svc) add(row("svc-reachable", "Build service", "Build service answers", S.FAIL, "no answer from the tunnel (127.0.0.1:7340/health)", "Check nxeon-modbuilder-tunnel and VM 88001 (docker ps); nothing can build until this is up."));
  else {
    add(row("svc-reachable", "Build service", "Build service answers", svc.ok ? S.PASS : S.FAIL, svc.ok ? "health ok" : "health answers ok:false", svc.ok ? "" : "Open the build service logs on VM 88001."));
    add(row("svc-auth", "Build service", "Build service auth mode", svc.auth === "api_key" ? S.PASS : S.WARN,
      `auth=${unit(svc.auth)}`,
      svc.auth === "api_key" ? "" : "Still on the owner's subscription login. Public launch needs a paid API key: API_KEY=<key> bash scripts/cyrus/deploy-modbuilder.sh, then re-run this check.",
      svc.auth === "api_key" ? S.PASS : S.FAIL));
    const pv = f.repo?.promptVersion;
    add(row("svc-prompt", "Build service", "Live promptVersion matches the repo", !pv ? S.INFO : svc.promptVersion === pv ? S.PASS : S.WARN,
      `live=${unit(svc.promptVersion)} repo=${unit(pv)}`, svc.promptVersion === pv || !pv ? "" : "The image is older/newer than this checkout: deploy the image built from the release you are launching (deploy-modbuilder.sh), or check out the matching release."));
    const sc = f.repo?.scannerSha256;
    add(row("svc-scanner", "Build service", "Live scanner is the repo's scan.js", !sc || !svc.scannerSha256 ? S.INFO : svc.scannerSha256 === sc ? S.PASS : S.FAIL,
      !sc || !svc.scannerSha256 ? "scanner hash not reported" : svc.scannerSha256 === sc ? "scan.js identical" : "scan.js differs from the repo", "Redeploy the image from this release; the scanner is a safety gate."));
    const q = Number(svc.queued ?? 0), run = Number(svc.running ?? 0);
    add(row("svc-idle", "Build service", "Queue and running builds", q > T.queueWarn ? S.WARN : S.PASS, `running=${run} queued=${q}`, q > T.queueWarn ? "A backlog right now: wait for it to drain before flipping the launch pair." : ""));
    if (/^\d+\.\d+$/.test(unit(svc.image)) && f.repo?.imageConst && svc.image === f.repo.imageConst && f.deployTagHint && f.deployTagHint !== `modbuilder:${svc.image}`) {
      add(row("svc-image", "Build service", "Image tag reported by /health", S.INFO, `health.image="${svc.image}" is a constant in server.js, not the Docker tag`, "Read the real tag with: ssh -J root@178.63.94.114 root@10.20.1.253 docker inspect -f '{{.Config.Image}}' modbuilder"));
    }
  }
  // guard smoke
  const g = f.guard;
  if (!g || !g.at) add(row("guard-smoke", "Build service", "Guard smoke result", S.WARN, "no recorded guard smoke", "Run scripts/cyrus/deploy-modbuilder.sh smoke step (records /var/lib/cyrus/guard-smoke.json) or the owner paste in the runbook step 3."));
  else {
    const a = ageMs(g.at, f.now);
    const st = g.result !== "ok" ? S.FAIL : a !== null && a > T.guardWarnDays * DAY ? S.WARN : S.PASS;
    add(row("guard-smoke", "Build service", "Guard smoke result", st, `${g.result}, ${a === null ? "age unknown" : days(a) + " d old"}`, st === S.PASS ? "" : g.result !== "ok" ? "The guard did NOT refuse the injection prompt: do not launch; investigate on VM 88001." : "Re-run the guard smoke (a few cents) after the latest image deploy."));
  }

  // ---- flags and settings
  if (!f.settings) add(row("settings-readable", "Flags", "Settings readable", S.FAIL, "the Setting table could not be read (DATABASE_URL / psql)", "Run on the primary as root with /opt/nxeon/.env readable."));
  else {
    add(row("pair", "Flags", "Launch pair moves together", pair.pub === pair.tok ? S.PASS : S.FAIL,
      `cyrus_studio_public_enabled=${pair.pub} cyrus_tok_live=${pair.tok}`,
      pair.pub === pair.tok ? "" : "The pair is split. Set both to the same value in Admin > Cyrus > Flags (guarded flip), never one alone."));
    if (isPublic) add(row("pair-auth", "Flags", "Public flip only with an API key", svc?.auth === "api_key" ? S.PASS : S.FAIL, `public=true auth=${unit(svc?.auth)}`, "Studio is PUBLIC on the owner's subscription login. Close it (Flags > CLOSE CYRUS) and swap to an API key first."));
    const live = truthy(set.cyrus_tok_live);
    const enforceDefaultTrue = set.cyrus_tok_enforce === undefined ? true : truthy(set.cyrus_tok_enforce);
    add(row("tok-enforce", "Flags", "Token enforcement on when tokens are live", live && !enforceDefaultTrue ? S.FAIL : S.PASS, `tok_live=${live} tok_enforce=${enforceDefaultTrue}`, live && !enforceDefaultTrue ? "cyrus_tok_enforce is off while tokens are live: builds are not metered. Set cyrus_tok_enforce=true." : ""));
    const wallet = truthy(env.CYRUS_WALLET_PAY), storage = truthy(env.CYRUS_STORAGE), addons = truthy(env.CYRUS_STORAGE_ADDONS);
    const combos = [];
    if (addons && !storage) combos.push("CYRUS_STORAGE_ADDONS=1 without CYRUS_STORAGE (add-ons inert)");
    if (wallet && !live) combos.push("CYRUS_WALLET_PAY=1 while cyrus_tok_live is off (wallet pays for tokens nobody can spend)");
    if (live && !wallet && !f.stripe?.keyMode?.startsWith?.("live")) combos.push("tokens live but no payment path (neither wallet pay nor a live Stripe key)");
    if (storage && !live && isPublic) combos.push("storage metering on while public is off");
    add(row("combos", "Flags", "Wallet / storage / tok_live combinations", combos.length ? S.WARN : S.PASS, combos.join("; ") || "consistent", combos.length ? "Fix the listed switch in the portal env (Admin > Cyrus > Flags env table shows each)." : ""));
    const ph = (f.placeholderKeys || []).filter((k) => set[k] === undefined);
    add(publicOnly("placeholders", "Flags", "Prices, quotas and caps are owner-set", ph.length ? S.WARN : S.PASS,
      ph.length ? `${ph.length} setting(s) still on a PLACEHOLDER default: ${ph.slice(0, 6).join(", ")}${ph.length > 6 ? ", ..." : ""}` : "no placeholder defaults in use",
      ph.length ? "Confirm each in Admin > Cyrus > Audit & settings (saving the default value is enough to mark it decided). Price/quota numbers are the owner's call." : ""));
    const cap = Number(set.cyrus_cost_platform_daily_cap_usd || 0);
    add(publicOnly("cost-cap", "Flags", "Platform daily AI spend cap set", cap > 0 ? S.PASS : S.WARN, `cyrus_cost_platform_daily_cap_usd=${cap || "0 (off)"}`, cap > 0 ? "" : "Set cyrus_cost_platform_daily_cap_usd so a bug or abuse cannot spend without limit."));
    const paused = truthy(set.cyrus_builds_paused);
    add(row("paused", "Flags", "Global build pause is off", paused ? S.WARN : S.PASS, `cyrus_builds_paused=${paused}`, paused ? "Builds are paused: unpause in Flags before launch." : ""));
  }
  // sound library licence
  const cleared = truthy(env.CYRUS_SOUND_LIBRARY_CLEARED);
  const L = f.ledger;
  if (!cleared) add(row("licence", "Legal", "Sound library licence ledger", S.PASS, "CYRUS_SOUND_LIBRARY_CLEARED is off: proprietary SFX stay hidden from customers", ""));
  else if (!L || !L.exists) add(row("licence", "Legal", "Sound library licence ledger", S.FAIL, "CYRUS_SOUND_LIBRARY_CLEARED=1 but no LICENCE-LEDGER.csv found", "Restore /tank/cyrus-library-staging/LICENCE-LEDGER.csv or turn the flag off."));
  else {
    const open = Object.entries(L.decisions || {}).filter(([k]) => !/^(INCLUDED|EXCLUDED|OWNED|REJECTED)$/i.test(k)).reduce((a, [, n]) => a + n, 0);
    add(row("licence", "Legal", "Sound library licence ledger", open ? S.WARN : L.included > 0 ? S.PASS : S.FAIL, `${L.rows} rows, ${L.included} INCLUDED, ${open} undecided`, open ? "Resolve the undecided ledger rows before customers hear them." : L.included ? "" : "Ledger has no INCLUDED rows."));
  }

  // ---- network
  const dns = f.dns || {};
  for (const [host, ips] of Object.entries(dns)) add(row(`dns-${host}`, "Network", `DNS ${host}`, ips && ips.length ? S.PASS : S.FAIL, ips && ips.length ? `${ips.length} address(es)` : "does not resolve", "Fix the A/CNAME record at Cloudflare."));
  for (const [host, t] of Object.entries(f.tls || {})) {
    if (!t) continue;
    const d = t.daysLeft;
    const st = d === null || d === undefined ? S.FAIL : d < T.certFailDays ? S.FAIL : d < T.certWarnDays ? S.WARN : S.PASS;
    add(row(`tls-${t.label || host}`, "Network", `TLS ${t.label || host}`, st, d === null || d === undefined ? `no certificate (${t.error || "unreachable"})` : `${d} days left${t.issuer ? " (" + t.issuer + ")" : ""}`, st === S.PASS ? "" : "Renew: certbot renew (origin) / check Cloudflare edge cert; alert fires at 14 d."));
  }
  if (f.cloudflare) {
    add(row("cf-reach", "Network", "Cloudflare reachable", f.cloudflare.reachable ? S.PASS : S.FAIL, f.cloudflare.reachable ? `edge answers (${f.cloudflare.status})` : "https://cyrus.my did not answer", "Check Cloudflare status and the origin."));
    add(row("realip", "Network", "Real client IP restored from Cloudflare", f.cloudflare.realipConf ? S.PASS : S.FAIL, f.cloudflare.realipConf ? "set_real_ip_from ranges present in nginx" : "no set_real_ip_from for Cloudflare in /etc/nginx", "Install /etc/nginx/conf.d/cloudflare-realip.conf (rate limits and the admin IP allowlist see only Cloudflare otherwise)."));
  }
  if (f.nginx) {
    add(row("nginx-syntax", "Network", "nginx config syntax", f.nginx.syntaxOk ? S.PASS : S.FAIL, f.nginx.syntaxOk ? "nginx -t ok" : String(f.nginx.error || "nginx -t failed").slice(0, 160), f.nginx.syntaxOk ? "" : "Fix before any reload; do not reload with a broken config."));
    const have = new Set(f.nginx.appPrefixes || []);
    const missing = f.nginx.appPrefixes ? REQUIRED_APP_PREFIXES.filter((p) => !have.has(p)) : [];
    add(row("nginx-paths", "Network", "nginx app-path list covers the app routes", !f.nginx.appPrefixes ? S.INFO : missing.length ? S.WARN : S.PASS,
      !f.nginx.appPrefixes ? "cyrus-my vhost not found" : missing.length ? `not in the explicit proxy list: /${missing.join(", /")} (they work through the try_files fallback with default 60 s timeouts and no rate limit)` : "all prefixes listed",
      missing.length ? "Add them to the `location ~ ^/(...)(/|$)` regex in /etc/nginx/sites-enabled/cyrus-my (or accept the fallback), then nginx -t && systemctl reload nginx." : ""));
  }

  // ---- money
  const st = f.stripe;
  if (st) {
    const mode = st.keyMode;
    add(publicOnly("stripe-mode", "Money", "Stripe mode", mode === "live" ? S.PASS : mode === "test" ? S.FAIL : S.FAIL, `key mode: ${mode}`, mode === "live" ? "" : "Stripe is not in LIVE mode. Put the live secret key and its webhook secret in /opt/nxeon/.env through the portal and promote."));
    add(publicOnly("stripe-webhook", "Money", "Stripe webhook endpoint", st.webhookSecretSet && st.webhookStatus && st.webhookStatus !== 404 && st.webhookStatus < 500 ? S.PASS : S.FAIL,
      `STRIPE_WEBHOOK_SECRET ${st.webhookSecretSet ? "set" : "NOT set"}; endpoint answers ${st.webhookStatus ?? "nothing"}`, "Create the live-mode webhook in Stripe -> https://nxeon.cloud/api/stripe/webhook, put its secret in the env, promote."));
  }

  // ---- storage and data
  const pk = f.packs;
  if (pk) add(row("packs", "Data", "Pack store reachable", !pk.store || pk.store === "off" ? S.WARN : pk.baseStatus && pk.baseStatus < 500 && pk.baseStatus !== 0 ? S.PASS : S.FAIL,
    pk.store && pk.store !== "off" ? `store=${pk.store} base answers ${pk.baseStatus ?? "nothing"}` : "CYRUS_PACK_STORE off", "Set CYRUS_PACK_STORE=local, CYRUS_PACK_LOCAL_DIR and CYRUS_PACK_PUBLIC_BASE (runbook step 5)."));
  for (const [k, label] of [["root", "/"], ["tank", "/tank"]]) {
    const d = f.disks?.[k];
    if (!d) continue;
    const st2 = d.pct >= T.diskFailPct ? S.FAIL : d.pct >= T.diskWarnPct ? S.WARN : S.PASS;
    add(row(`disk-${k}`, "Data", `Disk free ${label}`, st2, `${d.pct}% used, ${d.availGb} GB free`, st2 === S.PASS ? "" : `Free space on ${label} (logs, old builds, docker prune on VM) before launch; alert fires at ${T.diskWarnPct}%.`));
  }
  const b = f.backup;
  if (b) {
    const a = ageMs(b.lastSuccess, f.now);
    const st3 = a === null ? S.FAIL : a > T.backupFailHours * 3.6e6 ? S.FAIL : a > T.backupWarnHours * 3.6e6 ? S.WARN : S.PASS;
    add(row("backup-fresh", "Data", "Nightly backup freshness", st3, a === null ? "no LAST_SUCCESS recorded at the target" : `last success ${hours(a)} h ago`,
      st3 === S.PASS ? "" : "Install deploy/cyrus/cyrus-backup.timer with /etc/cyrus/backup-pubkey.asc, run scripts/cyrus/backup-nightly.sh --go once, and confirm LAST_SUCCESS."));
    add(publicOnly("backup-offbox", "Data", "Off-box encrypted copy exists", b.offboxLastSuccess ? S.PASS : S.FAIL, b.offboxLastSuccess ? `off-box success ${b.offboxLastSuccess}` : "no off-box (restic/rclone) success recorded; /tank is a single disk",
      b.offboxLastSuccess ? "" : "Set CYRUS_OFFBOX_REPO/PASSFILE (docs/cyrus/07-operations.md backups), run scripts/cyrus/backup-offbox.sh --go once, then restore-drill."));
  }
  const al = f.alerts;
  if (al) {
    add(row("alerts-unit", "Ops", "Alert timer active", al.timerActive ? S.PASS : S.FAIL, al.timerActive ? "cyrus-alerts.timer active" : "cyrus-alerts.timer not active", "Install deploy/cyrus/cyrus-alerts.{service,timer} and /etc/cyrus/alerts.env (Discord webhook + read-only DB URL), systemctl enable --now cyrus-alerts.timer."));
    add(row("alerts-webhook", "Ops", "Alert destination configured", al.webhookSet ? S.PASS : S.WARN, al.webhookSet ? "Discord webhook set" : "no CYRUS_ALERT_DISCORD_WEBHOOK in /etc/cyrus/alerts.env", "Alerts print to the journal only without a webhook; set it."));
  }
  if (f.statusPage) add(publicOnly("status-page", "Ops", "Public status page", f.statusPage.flagOn && f.statusPage.fileAgeMin !== null && f.statusPage.fileAgeMin < 30 ? S.PASS : S.WARN, f.statusPage.flagOn ? `status.json ${f.statusPage.fileAgeMin === null ? "missing" : f.statusPage.fileAgeMin + " min old"}` : "CYRUS_STATUS_PAGE off", "Optional: enable CYRUS_STATUS_PAGE=1 and the alert unit's status.json (docs/cyrus/07-operations.md)."));

  // ---- legal, sign-up, errors
  const lg = f.legal;
  if (lg) {
    const missing = Object.entries(lg.pages || {}).filter(([, c]) => !(c >= 200 && c < 400)).map(([k]) => k);
    add(row("legal-pages", "Legal", "Terms, privacy and AUP pages exist", missing.length ? S.FAIL : S.PASS, missing.length ? `not answering: ${missing.join(", ")}` : "terms, privacy, aup answer", missing.length ? "Publish the legal pages (app/legal/*) and promote." : ""));
    const linked = lg.signupLinks && lg.footerLinks;
    add(publicOnly("legal-linked", "Legal", "Legal pages linked from sign-up and footer", linked ? S.PASS : S.FAIL,
      `sign-up/sign-in links: ${lg.signupLinks ? "yes" : "NO"}; landing footer links: ${lg.footerLinks ? "yes" : "NO"}`, linked ? "" : "Add Terms/Privacy links (https://cyrus.my/legal/terms, /legal/privacy) to app/cyrus-host/sign-in/SignInView.tsx and apps/cyrus-site footer, publish."));
  }
  if (!f.settings) { /* reported above */ } else {
    const emails = String(set.preview_access_emails_modbuilder || "").split(",").map((s) => s.trim()).filter(Boolean);
    const gate = isPublic ? S.INFO : emails.length ? S.PASS : S.WARN;
    add(row("signup-gate", "Access", "Sign-up / build gating", gate, isPublic ? "PUBLIC: any verified account may build" : `private: ${emails.length} allow-listed account(s)`,
      isPublic ? "" : emails.length ? "" : "Nobody is allow-listed: add beta testers to preview_access_emails_modbuilder.", S.PASS));
  }
  if (f.errlog) add(row("errlog", "Ops", "Error logging endpoint on the Cyrus host", f.errlog.status >= 200 && f.errlog.status < 300 ? S.PASS : S.FAIL, `POST https://cyrus.my/api/log -> ${f.errlog.status || "no answer"}`, "Crashes on cyrus.my are not logged. /api/log is in the repo's CYRUS_APIS: promote the release that contains it and add api/log to the nginx proxy list."));

  // ---- eval
  const ev = f.eval;
  if (ev) {
    if (!ev.at) add(row("eval", "Quality", "Latest eval verdict", S.WARN, `no gate verdict found${ev.baselineExists ? "" : "; services/modbuilder/eval/baseline.json is not in the repo"}`, "Run scripts/cyrus/eval-gate-weekly.sh with CYRUS_EVAL_GATE_BUDGET_USD set (about $8), then accept the run as the baseline."));
    else {
      const a = ageMs(ev.at, f.now);
      const old = a !== null && a > T.evalFailDays * DAY ? S.FAIL : a !== null && a > T.evalWarnDays * DAY ? S.WARN : S.PASS;
      const low = ev.finalPassPct !== null && ev.finalPassPct < T.evalMinFinalPassPct ? S.FAIL : ev.verdict === "fail" ? S.FAIL : ev.verdict === "warn" || ev.verdict === "no-reference" ? S.WARN : S.PASS;
      const worst = ORDER.indexOf(old) <= ORDER.indexOf(low) ? old : low;
      add(publicOnly("eval", "Quality", "Latest eval verdict", worst,
        `verdict=${ev.verdict}, final pass ${ev.finalPassPct ?? "?"}% (min ${T.evalMinFinalPassPct}), pass@1 ${ev.passAt1Pct ?? "?"}%, ${a === null ? "age unknown" : days(a) + " d old"}`,
        worst === S.PASS ? "" : "Re-run the eval gate against the live image and review the regressions before launch."));
    }
  }
  return rows;
}

export function summarize(rows) {
  const out = {};
  for (const aud of ["beta", "public"]) {
    const c = { PASS: 0, WARN: 0, FAIL: 0, INFO: 0, SKIP: 0 };
    for (const r of rows) c[r[aud]]++;
    out[aud] = { ...c, verdict: c.FAIL ? "NO-GO" : "GO", blockers: rows.filter((r) => r[aud] === S.FAIL).map((r) => r.id) };
  }
  return out;
}

/** The full machine-readable result (what launch-check.sh --json writes and the admin tab reads). */
export function buildResult(f, T = THRESHOLDS) {
  const rows = evaluate(f, T);
  return { schema: LAUNCH_SCHEMA, at: f.now, host: f.host || null, rows, summary: summarize(rows) };
}

export function renderTable(result, mode = "beta") {
  const w = (s, n) => String(s).padEnd(n).slice(0, n);
  const lines = [`Cyrus launch check (${mode}) ${result.at}`, ""];
  const sorted = [...result.rows].sort((a, b) => ORDER.indexOf(a[mode]) - ORDER.indexOf(b[mode]));
  lines.push(`${w("STATUS", 6)} ${w("AREA", 14)} ${w("CHECK", 44)} DETAIL`);
  for (const r of sorted) {
    if (r[mode] === S.SKIP) continue;
    lines.push(`${w(r[mode], 6)} ${w(r.area, 14)} ${w(r.title, 44)} ${r.detail}`);
    if (r.action && (r[mode] === S.FAIL || r[mode] === S.WARN)) lines.push(`${" ".repeat(7)}-> ${r.action}`);
  }
  const s = result.summary;
  lines.push("", `private beta : ${s.beta.verdict}  (PASS ${s.beta.PASS}, WARN ${s.beta.WARN}, FAIL ${s.beta.FAIL})${s.beta.blockers.length ? "  blockers: " + s.beta.blockers.join(", ") : ""}`);
  lines.push(`public launch: ${s.public.verdict}  (PASS ${s.public.PASS}, WARN ${s.public.WARN}, FAIL ${s.public.FAIL})${s.public.blockers.length ? "  blockers: " + s.public.blockers.join(", ") : ""}`);
  return lines.join("\n");
}

/** Minimal CSV reader (quoted fields, doubled quotes) for the licence ledger. */
export function parseCsv(text) {
  const rows = []; let cur = [], field = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; } else field += c; }
    else if (c === '"') q = true;
    else if (c === ",") { cur.push(field); field = ""; }
    else if (c === "\n") { cur.push(field); rows.push(cur); cur = []; field = ""; }
    else if (c !== "\r") field += c;
  }
  if (field || cur.length) { cur.push(field); rows.push(cur); }
  return rows;
}

export function ledgerFacts(text) {
  const rows = parseCsv(text);
  if (!rows.length) return { exists: true, rows: 0, included: 0, decisions: {} };
  const di = rows[0].indexOf("decision");
  const decisions = {};
  for (const r of rows.slice(1)) { if (r.length < 2) continue; const d = (di >= 0 ? r[di] : "") || "UNKNOWN"; decisions[d] = (decisions[d] || 0) + 1; }
  return { exists: true, rows: rows.length - 1, included: decisions.INCLUDED || 0, decisions };
}

/** Pull the `location ~ ^/(a|b)(/|$)` alternatives out of an nginx vhost (first path segments, "api/cyrus" kept). */
export function nginxAppPrefixes(conf) {
  const out = new Set();
  for (const m of conf.matchAll(/location\s+~\s+\^\/\(([^)]+)\)\(\/\|\$\)/g)) for (const p of m[1].split("|")) out.add(p.trim());
  return [...out];
}

export function stripeKeyMode(key) {
  if (!key) return "none";
  if (/^(sk|rk)_live_/.test(key)) return "live";
  if (/^(sk|rk)_test_/.test(key)) return "test";
  return "unknown";
}

