// Cyrus launch check collector + CLI. READ ONLY: curl GET/HEAD (plus one empty POST to the error-log and webhook
// endpoints, which both refuse it), psql in a read-only transaction, nginx -t, openssl s_client, file reads.
// Prints no secret values (env values are only used for presence/mode). Evaluation lives in launch-eval.mjs.
//   node scripts/cyrus/lib/launch-check.mjs [beta|public] [--json FILE] [--facts]
// Env overrides (all optional): ENVF, SVC, CYRUS_PUBLIC_URL, CYRUS_NXEON_URL, CYRUS_ADMIN_HOST, CYRUS_NGINX_CONF,
// CYRUS_BACKUP_TARGET, CYRUS_OFFBOX_STATUS, CYRUS_EVAL_DIR, CYRUS_STATE_DIR, CYRUS_LIBRARY_DIR.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import dns from "node:dns/promises";
import { buildResult, ledgerFacts, nginxAppPrefixes, renderTable, stripeKeyMode } from "./launch-eval.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "../../..");
const E = process.env;
const ENVF = E.ENVF || "/opt/nxeon/.env";
const SVC = E.SVC || "http://127.0.0.1:7340";
const CYRUS = E.CYRUS_PUBLIC_URL || "https://cyrus.my";
const NXEON = E.CYRUS_NXEON_URL || "https://nxeon.cloud";
const STATE = E.CYRUS_STATE_DIR || "/var/lib/cyrus";
const LIB = E.CYRUS_LIBRARY_DIR || "/tank/cyrus-library-staging";

const sh = (cmd, args, t = 15000, input) => { try { return execFileSync(cmd, args, { encoding: "utf8", timeout: t, stdio: ["pipe", "pipe", "pipe"], input }).trim(); } catch (e) { return { error: String(e.stderr || e.message || e).trim().split("\n").slice(-2).join(" ").slice(0, 200) }; } };
const str = (v) => (typeof v === "string" ? v : "");
const readText = (p) => { try { return readFileSync(p, "utf8"); } catch { return null; } };
const mtimeMin = (p, now) => { try { return Math.round((now - statSync(p).mtimeMs) / 60000); } catch { return null; } };
const sha256 = (p) => { try { return createHash("sha256").update(readFileSync(p)).digest("hex"); } catch { return null; } };

function envFile(p) {
  const out = {}; const t = readText(p); if (!t) return out;
  for (const l of t.split("\n")) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l.trim()); if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, ""); }
  return out;
}
const curl = (url, { method = "GET", head = false, ua } = {}) => {
  const a = ["-s", "-m", "10", "-o", "/dev/null", "-w", "%{http_code}"];
  if (head) a.push("-I"); else if (method !== "GET") a.push("-X", method, "-H", "content-type: application/json", "-d", "{}");
  if (ua) a.push("-A", ua);
  const r = sh("curl", [...a, url], 14000); return typeof r === "string" ? Number(r) : 0;
};
const curlBody = (url) => { const r = sh("curl", ["-s", "-m", "8", url], 12000); return typeof r === "string" ? r : ""; };

function certDays(host, port, servername, now) {
  const r = sh("openssl", ["s_client", "-connect", `${host}:${port}`, "-servername", servername, "-brief"], 12000, "");
  // -brief prints to stderr; use the x509 route for the date
  const pem = sh("sh", ["-c", `echo | openssl s_client -connect ${host}:${port} -servername ${servername} 2>/dev/null | openssl x509 -noout -enddate -issuer 2>/dev/null`], 15000);
  if (typeof pem !== "string" || !pem) return { daysLeft: null, error: typeof r === "object" ? r.error : "no certificate" };
  const m = /notAfter=(.*)/.exec(pem); const iss = /O\s*=\s*([^,\n]+)/.exec(pem) || /CN\s*=\s*([^,\n]+)/.exec(pem);
  const t = m ? Date.parse(m[1]) : NaN;
  return { daysLeft: Number.isFinite(t) ? Math.floor((t - now) / 86400000) : null, issuer: iss ? iss[1].trim() : "" };
}

async function collect() {
  const now = Date.now();
  const env = { ...envFile(ENVF) };
  const f = { now: new Date(now).toISOString(), host: sh("hostname", []) };
  f.env = {};
  for (const [k, v] of Object.entries(env)) if (/^CYRUS_/.test(k) && !/TOKEN|SECRET|KEY|PASS/.test(k)) f.env[k] = v;

  // repo facts
  const prompts = readText(join(ROOT, "services/modbuilder/prompts.js")) || "";
  const server = readText(join(ROOT, "services/modbuilder/server.js")) || "";
  f.repo = {
    promptVersion: (/const PROMPT_VERSION = "([^"]+)"/.exec(prompts) || [])[1] || null,
    scannerSha256: sha256(join(ROOT, "services/modbuilder/scan.js")),
    registrySha256: null,
    imageConst: (/service: "nxeon-modbuilder", image: "([^"]+)"/.exec(server) || [])[1] || null,
  };

  // build service
  try { const h = JSON.parse(curlBody(`${SVC}/health`)); f.svc = { ok: !!h.ok, auth: h.auth, image: h.image, promptVersion: h.promptVersion, running: h.running, queued: h.queued, scannerSha256: h.release?.scannerSha256 || null, registrySha256: h.release?.registrySha256 || null }; } catch { f.svc = null; }
  try { const g = JSON.parse(readText(join(STATE, "guard-smoke.json"))); f.guard = { at: g.at, result: g.result }; } catch { f.guard = null; }

  // settings (read-only transaction); DATABASE_URL never printed
  f.settings = null; f.placeholderKeys = [];
  try { f.placeholderKeys = JSON.parse(readFileSync(join(HERE, "placeholder-keys.json"), "utf8")); } catch { /* none */ }
  const url = (env.DATABASE_URL || "").replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace("?&", "?").replace(/[?&]+$/, "");
  if (url) {
    const r = sh("psql", [url, "-XAtq", "-v", "ON_ERROR_STOP=1", "-F", "\t", "-c", "select key, value from \"Setting\" where key like 'cyrus\\_%' or key = 'preview_access_emails_modbuilder'"], 20000);
    if (typeof r === "string") { f.settings = {}; for (const l of r.split("\n")) { const [k, ...v] = l.split("\t"); if (k) f.settings[k] = v.join("\t"); } }
  }

  // licence ledger
  const led = readText(join(LIB, "LICENCE-LEDGER.csv"));
  f.ledger = led === null ? { exists: false } : ledgerFacts(led);

  // network
  const adminHost = E.CYRUS_ADMIN_HOST || env.CYRUS_ADMIN_HOST || "";
  const hosts = ["cyrus.my", ...(adminHost ? [adminHost] : [])];
  f.dns = {};
  for (const h of hosts) { try { f.dns[h] = await dns.resolve4(h); } catch { f.dns[h] = []; } }
  f.tls = {
    "edge-cyrus.my": { label: "cyrus.my (edge)", ...certDays("cyrus.my", 443, "cyrus.my", now) },
    "origin-cyrus.my": { label: "cyrus.my (origin)", ...certDays("127.0.0.1", 443, "cyrus.my", now) },
  };
  if (adminHost) f.tls["edge-admin"] = { label: "admin host", ...certDays(adminHost, 443, adminHost, now) };
  const cfStatus = curl(`${CYRUS}/`, { head: true });
  const cfConf = ["/etc/nginx/conf.d", "/etc/nginx/snippets"].flatMap((d) => { try { return readdirSync(d).map((x) => readText(join(d, x)) || ""); } catch { return []; } }).join("\n");
  f.cloudflare = { reachable: cfStatus > 0 && cfStatus < 500, status: cfStatus, realipConf: /set_real_ip_from\s+(173\.245|103\.21|2400:cb00)/.test(cfConf) };
  const confPath = E.CYRUS_NGINX_CONF || "/etc/nginx/sites-enabled/cyrus-my";
  const conf = readText(confPath);
  const t = sh("nginx", ["-t"], 15000);
  f.nginx = { syntaxOk: typeof t === "string" || /syntax is ok/.test(String(t.error || "")), error: typeof t === "object" && !/syntax is ok/.test(t.error) ? t.error : null, appPrefixes: conf ? nginxAppPrefixes(conf) : null };

  // money
  f.stripe = { keyMode: stripeKeyMode(env.STRIPE_SECRET_KEY), webhookSecretSet: !!env.STRIPE_WEBHOOK_SECRET, webhookStatus: curl(`${NXEON}/api/stripe/webhook`, { method: "POST" }) };

  // packs
  const store = env.CYRUS_PACK_STORE || "";
  f.packs = { store, base: env.CYRUS_PACK_PUBLIC_BASE ? "set" : "", baseStatus: env.CYRUS_PACK_PUBLIC_BASE ? curl(`${env.CYRUS_PACK_PUBLIC_BASE.replace(/\/$/, "")}/`, { head: true }) : null };

  // disks
  f.disks = {};
  for (const [k, p] of [["root", "/"], ["tank", "/tank"]]) {
    const r = sh("df", ["-Pk", p]); if (typeof r !== "string") continue;
    const c = r.split("\n").pop().split(/\s+/); f.disks[k] = { pct: Number(String(c[4]).replace("%", "")), availGb: Math.round(Number(c[3]) / 1048576) };
  }

  // backups
  const target = E.CYRUS_BACKUP_TARGET || env.CYRUS_BACKUP_TARGET || "root@178.63.94.114:/tank/cyrus-backups";
  let last = null;
  if (target.includes(":")) { const [h, d] = [target.split(":")[0], target.slice(target.indexOf(":") + 1)]; const r = sh("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=8", h, `cat '${d}/LAST_SUCCESS'`], 15000); if (typeof r === "string") last = r; }
  else last = (readText(join(target, "LAST_SUCCESS")) || "").trim() || null;
  const off = readText(E.CYRUS_OFFBOX_STATUS || join(STATE, "offbox-last-success"));
  f.backup = { lastSuccess: last, offboxLastSuccess: off ? off.trim() : null };

  // alerts
  const a = sh("systemctl", ["is-active", "cyrus-alerts.timer"]);
  const aenv = envFile("/etc/cyrus/alerts.env");
  f.alerts = { timerActive: a === "active", webhookSet: !!(aenv.CYRUS_ALERT_DISCORD_WEBHOOK || E.CYRUS_ALERT_DISCORD_WEBHOOK) };
  f.statusPage = { flagOn: env.CYRUS_STATUS_PAGE === "1" || env.CYRUS_STATUS_PAGE === "true", fileAgeMin: mtimeMin(join(STATE, "status.json"), now) };

  // legal, sign-up, error log
  const pages = { terms: curl(`${NXEON}/legal/terms`, { head: true }), privacy: curl(`${NXEON}/legal/privacy`, { head: true }), aup: curl(`${NXEON}/legal/aup`, { head: true }) };
  const signup = (readText(join(ROOT, "app/cyrus-host/sign-in/SignInView.tsx")) || "") + (readText(join(ROOT, "app/cyrus-host/sign-up/page.tsx")) || "");
  const landing = readText("/var/www/cyrus.my/index.html") || readText(join(ROOT, "apps/cyrus-site/src/index.html")) || "";
  f.legal = { pages, signupLinks: /\/legal\/(terms|privacy)/.test(signup), footerLinks: /\/legal\/(terms|privacy)/.test(landing) };
  f.errlog = { status: curl(`${CYRUS}/api/log`, { method: "POST" }) };

  // eval verdict: newest gate.json that carries the gate schema
  f.eval = { at: null, baselineExists: existsSync(join(ROOT, "services/modbuilder/eval/baseline.json")) };
  const evalDir = E.CYRUS_EVAL_DIR || "/root/cyrus-eval";
  let best = null;
  try { for (const d of readdirSync(evalDir)) { const p = join(evalDir, d, "gate.json"); if (existsSync(p)) { const m = statSync(p).mtimeMs; if (!best || m > best.m) best = { p, m }; } } } catch { /* none */ }
  if (best) { try { const v = JSON.parse(readFileSync(best.p, "utf8")); if (v.schema === "cyrus-eval-gate-1") f.eval = { ...f.eval, at: v.createdAt, verdict: v.verdict, finalPassPct: v.totals?.finalPassPct ?? null, passAt1Pct: v.totals?.passAt1Pct ?? null }; } catch { /* ignore */ } }
  return f;
}

const args = process.argv.slice(2);
const mode = args.find((a) => a === "beta" || a === "public") || "beta";
const jsonIdx = args.indexOf("--json");
const facts = await collect();
if (args.includes("--facts")) { console.log(JSON.stringify(facts, null, 1)); process.exit(0); }
const result = buildResult(facts);
console.log(renderTable(result, mode));
const out = jsonIdx >= 0 ? args[jsonIdx + 1] : E.CYRUS_LAUNCH_JSON;
if (out) { try { mkdirSync(dirname(out), { recursive: true }); writeFileSync(out, JSON.stringify(result)); } catch (e) { console.error(`(result not saved: ${str(e.message)})`); } }
process.exit(result.summary[mode].verdict === "GO" ? 0 : 1);

