    if (typeof r === "string") { f.settings = {}; for (const l of r.split("\n")) { const [k, ...v] = l.split("\t"); if (k) f.settings[k] = v.join("\t"); } }
  }

  // licence ledger
  const led = readText(join(LIB, "LICENCE-LEDGER.csv"));
  f.ledger = led === null ? { exists: false } : ledgerFacts(led);

  // network
  const adminHost = E.CYRUS_ADMIN_HOST || env.CYRUS_ADMIN_HOST || "";
  const hosts = ["cyrus.my", ...(adminHost ? [adminHost] : [])];
  f.dns = {};
  for (const h of hosts) { try { f.dns[h] = await dns.resolve4(h); } catch { f.dns[h] = []; } }
  f.tls = {
    "edge-cyrus.my": { label: "cyrus.my (edge)", ...certDays("cyrus.my", 443, "cyrus.my", now) },
    "origin-cyrus.my": { label: "cyrus.my (origin)", ...certDays("127.0.0.1", 443, "cyrus.my", now) },
  };
  if (adminHost) f.tls["edge-admin"] = { label: "admin host", ...certDays(adminHost, 443, adminHost, now) };
  const cfStatus = curl(`${CYRUS}/`, { head: true });
  const cfConf = ["/etc/nginx/conf.d", "/etc/nginx/snippets"].flatMap((d) => { try { return readdirSync(d).map((x) => readText(join(d, x)) || ""); } catch { return []; } }).join("\n");
  f.cloudflare = { reachable: cfStatus > 0 && cfStatus < 500, status: cfStatus, realipConf: /set_real_ip_from\s+(173\.245|103\.21|2400:cb00)/.test(cfConf) };
  const confPath = E.CYRUS_NGINX_CONF || "/etc/nginx/sites-enabled/cyrus-my";
  const conf = readText(confPath);
  const t = sh("nginx", ["-t"], 15000);
  f.nginx = { syntaxOk: typeof t === "string" || /syntax is ok/.test(String(t.error || "")), error: typeof t === "object" && !/syntax is ok/.test(t.error) ? t.error : null, appPrefixes: conf ? nginxAppPrefixes(conf) : null };

  // money
  f.stripe = { keyMode: stripeKeyMode(env.STRIPE_SECRET_KEY), webhookSecretSet: !!env.STRIPE_WEBHOOK_SECRET, webhookStatus: curl(`${NXEON}/api/stripe/webhook`, { method: "POST" }) };

  // packs
  const store = env.CYRUS_PACK_STORE || "";
  f.packs = { store, base: env.CYRUS_PACK_PUBLIC_BASE ? "set" : "", baseStatus: env.CYRUS_PACK_PUBLIC_BASE ? curl(`${env.CYRUS_PACK_PUBLIC_BASE.replace(/\/$/, "")}/`, { head: true }) : null };

  // disks
  f.disks = {};
  for (const [k, p] of [["root", "/"], ["tank", "/tank"]]) {
    const r = sh("df", ["-Pk", p]); if (typeof r !== "string") continue;
    const c = r.split("\n").pop().split(/\s+/); f.disks[k] = { pct: Number(String(c[4]).replace("%", "")), availGb: Math.round(Number(c[3]) / 1048576) };
  }

  // backups
  const target = E.CYRUS_BACKUP_TARGET || env.CYRUS_BACKUP_TARGET || "root@178.63.94.114:/tank/cyrus-backups";
  let last = null;
  if (target.includes(":")) { const [h, d] = [target.split(":")[0], target.slice(target.indexOf(":") + 1)]; const r = sh("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=8", h, `cat '${d}/LAST_SUCCESS'`], 15000); if (typeof r === "string") last = r; }
  else last = (readText(join(target, "LAST_SUCCESS")) || "").trim() || null;
  const off = readText(E.CYRUS_OFFBOX_STATUS || join(STATE, "offbox-last-success"));
  f.backup = { lastSuccess: last, offboxLastSuccess: off ? off.trim() : null };

  // alerts
  const a = sh("systemctl", ["is-active", "cyrus-alerts.timer"]);
  const aenv = envFile("/etc/cyrus/alerts.env");
  f.alerts = { timerActive: a === "active", webhookSet: !!(aenv.CYRUS_ALERT_DISCORD_WEBHOOK || E.CYRUS_ALERT_DISCORD_WEBHOOK) };
  f.statusPage = { flagOn: env.CYRUS_STATUS_PAGE === "1" || env.CYRUS_STATUS_PAGE === "true", fileAgeMin: mtimeMin(join(STATE, "status.json"), now) };

  // legal, sign-up, error log
  const pages = { terms: curl(`${NXEON}/legal/terms`, { head: true }), privacy: curl(`${NXEON}/legal/privacy`, { head: true }), aup: curl(`${NXEON}/legal/aup`, { head: true }) };
  const signup = (readText(join(ROOT, "app/cyrus-host/sign-in/SignInView.tsx")) || "") + (readText(join(ROOT, "app/cyrus-host/sign-up/page.tsx")) || "");
  const landing = readText("/var/www/cyrus.my/index.html") || readText(join(ROOT, "apps/cyrus-site/src/index.html")) || "";
  f.legal = { pages, signupLinks: /\/legal\/(terms|privacy)/.test(signup), footerLinks: /\/legal\/(terms|privacy)/.test(landing) };
  f.errlog = { status: curl(`${CYRUS}/api/log`, { method: "POST" }) };

  // eval verdict: newest gate.json that carries the gate schema
  f.eval = { at: null, baselineExists: existsSync(join(ROOT, "services/modbuilder/eval/baseline.json")) };
  const evalDir = E.CYRUS_EVAL_DIR || "/root/cyrus-eval";
  let best = null;
  try { for (const d of readdirSync(evalDir)) { const p = join(evalDir, d, "gate.json"); if (existsSync(p)) { const m = statSync(p).mtimeMs; if (!best || m > best.m) best = { p, m }; } } } catch { /* none */ }
  if (best) { try { const v = JSON.parse(readFileSync(best.p, "utf8")); if (v.schema === "cyrus-eval-gate-1") f.eval = { ...f.eval, at: v.createdAt, verdict: v.verdict, finalPassPct: v.totals?.finalPassPct ?? null, passAt1Pct: v.totals?.passAt1Pct ?? null }; } catch { /* ignore */ } }
  return f;
}

const args = process.argv.slice(2);
const mode = args.find((a) => a === "beta" || a === "public") || "beta";
const jsonIdx = args.indexOf("--json");
const facts = await collect();
if (args.includes("--facts")) { console.log(JSON.stringify(facts, null, 1)); process.exit(0); }
