// ---------------------------------------------------------------------------
// Launch readiness (GO / NO-GO). The checks are evaluated by scripts/cyrus/launch-check.sh (pure logic in
// scripts/cyrus/lib/launch-eval.mjs); it writes its result as JSON (hourly timer, or `--json FILE`). The tab only
// PARSES that file, so the owner sees exactly what the command line says. parseLaunchCheck is PURE (unit-tested).
// ---------------------------------------------------------------------------
export type LaunchStatus = "PASS" | "WARN" | "FAIL" | "INFO" | "SKIP";
export type LaunchRow = { id: string; area: string; title: string; beta: LaunchStatus; public: LaunchStatus; detail: string; action: string };
export type LaunchAudience = { PASS: number; WARN: number; FAIL: number; INFO: number; SKIP: number; verdict: "GO" | "NO-GO"; blockers: string[] };
export type LaunchCheck = { at: string; host: string | null; rows: LaunchRow[]; beta: LaunchAudience; public: LaunchAudience; source: string };

const STATUSES = ["PASS", "WARN", "FAIL", "INFO", "SKIP"];
const asStatus = (v: unknown): LaunchStatus => (STATUSES.includes(String(v)) ? (v as LaunchStatus) : "INFO");

export function parseLaunchCheck(json: unknown, source = ""): LaunchCheck | null {
  const j = json as { schema?: string; at?: string; host?: string | null; rows?: unknown[] } | null;
  if (!j || j.schema !== "cyrus-launch-check-1" || !Array.isArray(j.rows)) return null;
  const rows: LaunchRow[] = j.rows.slice(0, 200).map((r) => {
    const x = r as Record<string, unknown>;
    return { id: String(x.id ?? "").slice(0, 60), area: String(x.area ?? "").slice(0, 40), title: String(x.title ?? "").slice(0, 120), beta: asStatus(x.beta), public: asStatus(x.public), detail: String(x.detail ?? "").slice(0, 400), action: String(x.action ?? "").slice(0, 500) };
  });
  const sum = (k: "beta" | "public"): LaunchAudience => {
    const c = { PASS: 0, WARN: 0, FAIL: 0, INFO: 0, SKIP: 0 };
    for (const r of rows) c[r[k]]++;
    return { ...c, verdict: c.FAIL ? "NO-GO" : "GO", blockers: rows.filter((r) => r[k] === "FAIL").map((r) => r.id) };
  };
  return { at: String(j.at ?? ""), host: j.host ?? null, rows, beta: sum("beta"), public: sum("public"), source };
}

export async function loadLaunchCheck(): Promise<LaunchCheck | null> {
  const p = process.env.CYRUS_LAUNCH_JSON || "/var/lib/cyrus/launch-check.json";
  try {
    return parseLaunchCheck(JSON.parse((await readFile(p, "utf8")).slice(0, 400_000)), p);
  } catch {
    return null;
  }
}
EOF
