import type { Metadata } from "next";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { loadLaunchCheck, type LaunchStatus } from "@/lib/cyrus/admin/readiness";
import { Badge } from "@/components/ui/primitives";
import { Empty, Section, TableWrap, tdRow, thCls, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Launch check");
}

const TONE: Record<LaunchStatus, "green" | "amber" | "red" | "slate"> = { PASS: "green", WARN: "amber", FAIL: "red", INFO: "slate", SKIP: "slate" };
const ORDER: LaunchStatus[] = ["FAIL", "WARN", "PASS", "INFO", "SKIP"];

/** GO / NO-GO for a private beta and for a public launch: the result of scripts/cyrus/launch-check.sh (read only). */
export default async function CyrusLaunchCheck() {
  await requireCyrusAdmin("launch");
  const r = await loadLaunchCheck();
  if (!r) {
    return (
      <Section title="Launch check" sub="GO / NO-GO for a private beta and for a public launch.">
        <Empty waitsFor="scripts/cyrus/launch-check.sh --json /var/lib/cyrus/launch-check.json (install deploy/cyrus/cyrus-launch-check.timer)">No launch check result has been written yet.</Empty>
      </Section>
    );
  }
  const stale = Date.now() - Date.parse(r.at) > 3 * 3_600_000;
  return (
    <div data-cyrus-launch>
      <div className="mb-4 flex flex-wrap items-center gap-2">
