// Cyrus alert evaluation: PURE decision functions used by scripts/cyrus/alert-check.sh (kind "signal" / "cert").
// Each takes measured facts + thresholds and returns a problem text, or "" when fine. Unit-tested in
// test/cyrus-alert-eval.test.ts. Thresholds are Setting keys (cyrus_alert_*) with the defaults below:
// PLACEHOLDER pending the owner (starting points, not measurements); the admin Audit & settings tab edits them.

export const ALERT_DEFAULTS = {
  cyrus_alert_queue_depth: 20,        // builds queued at once
  cyrus_alert_queue_wait_min: 15,     // oldest queued build waited this long
  cyrus_alert_build_fail_pct: 50,     // % of the last hour's finished builds failed ...
  cyrus_alert_build_fail_min: 5,       // ... with at least this many finished
  cyrus_alert_ai_burst_count: 5,       // ai_unavailable / session-limit failures in 15 min
  cyrus_alert_cert_days: 14,          // certificate days left
  cyrus_alert_error_rate_10m: 30,     // client+server ErrorLog occurrences in 10 min
  cyrus_alert_ledger_mismatch: 0,     // accounts whose balance differs from the ledger sum (0 = any is an alert)
  cyrus_alert_webhook_failures: 3,    // dead-letter or failed Stripe/webhook deliveries in 24 h
};

const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
/** Merge stored Setting strings over the defaults (a bad value falls back to the default). */
export function thresholds(stored = {}) {
  const t = {};
  for (const [k, d] of Object.entries(ALERT_DEFAULTS)) t[k] = num(stored[k], d);
  return t;
}

export function queueProblem(f, t) {
  const out = [];
  if (f.depth > t.cyrus_alert_queue_depth) out.push(`${f.depth} builds queued (limit ${t.cyrus_alert_queue_depth})`);
  if (f.oldestWaitMin > t.cyrus_alert_queue_wait_min) out.push(`oldest queued build has waited ${Math.round(f.oldestWaitMin)} min (limit ${t.cyrus_alert_queue_wait_min})`);
  return out.join("; ");
}

export function failureRateProblem(f, t) {
  if (f.finished < t.cyrus_alert_build_fail_min) return "";
  const pct = (f.failed * 100) / f.finished;
  return pct > t.cyrus_alert_build_fail_pct ? `${f.failed}/${f.finished} builds failed in the last hour (${Math.round(pct)}%, limit ${t.cyrus_alert_build_fail_pct}%)` : "";
}

/** ai_unavailable / session-limit / rate-limit failures bunching up: the AI backend (or the login/key) is the problem. */
export function aiBurstProblem(f, t) {
  const n = (f.ai_unavailable || 0) + (f.session_limit || 0);
  return n >= t.cyrus_alert_ai_burst_count ? `${n} AI backend failures in 15 min (${f.ai_unavailable || 0} unavailable, ${f.session_limit || 0} session limit; limit ${t.cyrus_alert_ai_burst_count})` : "";
}

export function certProblem(f, t) {
  if (f.daysLeft === null || f.daysLeft === undefined) return `${f.host}: no certificate readable (${f.error || "unreachable"})`;
  return f.daysLeft < t.cyrus_alert_cert_days ? `${f.host} certificate expires in ${f.daysLeft} days (limit ${t.cyrus_alert_cert_days})` : "";
}

/** Token ledger anomalies: balance != sum(ledger), negative balances, reservations stuck for hours. */
export function ledgerProblem(f, t) {
  const out = [];
  if (f.mismatched > t.cyrus_alert_ledger_mismatch) out.push(`${f.mismatched} account(s) whose balance differs from the ledger sum`);
  if (f.negative > 0) out.push(`${f.negative} account(s) with a negative balance`);
  if (f.staleReservations > 0) out.push(`${f.staleReservations} token reservation(s) held for over 2 h`);
  return out.join("; ");
}

export function errorRateProblem(f, t) {
  return f.occurrences10m > t.cyrus_alert_error_rate_10m ? `${f.occurrences10m} error log occurrences in 10 min (limit ${t.cyrus_alert_error_rate_10m}; top: ${f.top || "?"})` : "";
}

export function webhookProblem(f, t) {
  const n = (f.dead || 0) + (f.failed24h || 0);
  return n >= t.cyrus_alert_webhook_failures ? `${n} webhook failures in 24 h (${f.dead || 0} dead-lettered, ${f.failed24h || 0} payment webhook errors; limit ${t.cyrus_alert_webhook_failures})` : "";
}

export const SIGNALS = { queue: queueProblem, failureRate: failureRateProblem, aiBurst: aiBurstProblem, cert: certProblem, ledger: ledgerProblem, errorRate: errorRateProblem, webhook: webhookProblem };

/** Public status JSON (no detail text): component states from the rule results. */
export const STATUS_COMPONENTS = [
  { id: "studio", name: "Studio and sign-in", rules: ["health-down", "health-degraded", "cert-cyrus-my", "error-rate"] },
  { id: "builds", name: "Mod builds", rules: ["build-failure-rate", "build-queue-stuck", "queue-depth", "ai-backend-burst"] },
  { id: "payments", name: "Wallet and payments", rules: ["webhook-failures", "ledger-anomaly"] },
];
/** results: [{id, firing, severity}] -> { status, components } */
export function publicStatus(results, at) {
  const by = Object.fromEntries(results.map((r) => [r.id, r]));
  const components = STATUS_COMPONENTS.map((c) => {
    const f = c.rules.map((id) => by[id]).filter((r) => r && r.firing);
    return { id: c.id, name: c.name, status: f.some((r) => r.severity === "critical") ? "outage" : f.length ? "degraded" : "operational" };
  });
  const status = components.some((c) => c.status === "outage") ? "outage" : components.some((c) => c.status === "degraded") ? "degraded" : "operational";
  return { schema: "cyrus-status-1", at, status, components };
}
