<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>Cyrus status</title>
<style>
:root{color-scheme:dark;--bg:#000;--fg:#f4f4f5;--mut:#a1a1aa;--ok:#4ade80;--warn:#fbbf24;--bad:#f87171;--line:#27272a}
@media (prefers-color-scheme:light){:root{color-scheme:light;--bg:#fff;--fg:#18181b;--mut:#52525b;--ok:#15803d;--warn:#b45309;--bad:#b91c1c;--line:#e4e4e7}}
body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.5 system-ui,sans-serif}
main{max-width:640px;margin:0 auto;padding:32px 16px}
h1{font-size:1.4rem;margin:0 0 4px}
.sub{color:var(--mut);font-size:.9rem;margin:0 0 24px}
.row{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid var(--line)}
.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:8px;background:var(--mut)}
.operational .dot{background:var(--ok)}.degraded .dot{background:var(--warn)}.outage .dot{background:var(--bad)}
</style>
</head>
<body>
<main>
<h1>Cyrus status</h1>
<p class="sub" id="sub">Checking...</p>
<div id="rows"></div>
<p class="sub"><a href="/" style="color:inherit">Back to Cyrus</a></p>
</main>
<script>
(function(){
  var L={operational:"Operational",degraded:"Degraded",outage:"Outage"};
  function show(t){document.getElementById("sub").textContent=t}
  fetch("/status.json",{cache:"no-store"}).then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(s){
    if(!s||s.schema!=="cyrus-status-1")throw 0;
    var age=Date.now()-Date.parse(s.at);
    show(age>20*60000?"Status data is out of date ("+Math.round(age/60000)+" min old)":"Overall: "+(L[s.status]||s.status)+". Updated "+new Date(s.at).toUTCString());
    var rows=document.getElementById("rows");
    s.components.forEach(function(c){var d=document.createElement("div");d.className="row "+c.status;
      var a=document.createElement("span");var dot=document.createElement("span");dot.className="dot";a.appendChild(dot);a.appendChild(document.createTextNode(c.name));
      var b=document.createElement("span");b.textContent=L[c.status]||c.status;d.appendChild(a);d.appendChild(b);rows.appendChild(d)});
  }).catch(function(){show("The status feed is not available right now.")});
})();
</script>
</body>
</html>
EOF
