type Mod = { evaluate: (f: unknown) => Row[]; summarize: (r: Row[]) => Record<string, { verdict: string; FAIL: number; blockers: string[] }>; buildResult: (f: unknown) => { rows: Row[]; summary: unknown; at: string }; renderTable: (r: unknown, m: string) => string; parseCsv: (t: string) => string[][]; ledgerFacts: (t: string) => { rows: number; included: number; decisions: Record<string, number> }; nginxAppPrefixes: (c: string) => string[]; stripeKeyMode: (k: string) => string; REQUIRED_APP_PREFIXES: string[]; THRESHOLDS: Record<string, number> };
const mod = (): Promise<Mod> => import(path.join(ROOT, "scripts/cyrus/lib/launch-eval.mjs"));

const NOW = "2026-10-14T12:00:00.000Z";
const hoursAgo = (h: number) => new Date(Date.parse(NOW) - h * 3.6e6).toISOString();
function healthy(): Record<string, unknown> {
  return {
    now: NOW, host: "t",
    repo: { promptVersion: "mb-1", scannerSha256: "aa", imageConst: "0.5" },
    svc: { ok: true, auth: "api_key", image: "0.9", promptVersion: "mb-1", running: 0, queued: 0, scannerSha256: "aa" },
    guard: { at: hoursAgo(5), result: "ok" },
    settings: { cyrus_studio_public_enabled: "false", cyrus_tok_live: "false", preview_access_emails_modbuilder: "a@b.c", cyrus_cost_platform_daily_cap_usd: "50" },
    env: {}, placeholderKeys: ["cyrus_tok_plan_free_games"],
    ledger: { exists: true, rows: 10, included: 8, decisions: { INCLUDED: 8, EXCLUDED: 2 } },
    dns: { "cyrus.my": ["1.2.3.4"] },
    tls: { "edge-cyrus.my": { label: "cyrus.my (edge)", daysLeft: 60 } },
    cloudflare: { reachable: true, status: 200, realipConf: true },
    nginx: { syntaxOk: true, appPrefixes: [] },
    stripe: { keyMode: "live", webhookSecretSet: true, webhookStatus: 400 },
    packs: { store: "local", baseStatus: 200 },
    disks: { root: { pct: 50, availGb: 20 }, tank: { pct: 10, availGb: 2000 } },
    backup: { lastSuccess: hoursAgo(10), offboxLastSuccess: hoursAgo(10) },
    alerts: { timerActive: true, webhookSet: true },
    statusPage: { flagOn: false, fileAgeMin: null },
    legal: { pages: { terms: 200, privacy: 200, aup: 200 }, signupLinks: true, footerLinks: true },
    errlog: { status: 204 },
    eval: { at: hoursAgo(48), verdict: "pass", finalPassPct: 96, passAt1Pct: 70, baselineExists: true },
  };
}
const byId = (rows: Row[], id: string) => rows.find((r) => r.id === id)!;

describe("launch-eval: verdicts", () => {
  it("a healthy private deployment is GO for beta", async () => {
    const m = await mod();
    const f = healthy(); (f.nginx as { appPrefixes: string[] }).appPrefixes = m.REQUIRED_APP_PREFIXES;
    const s = m.summarize(m.evaluate(f));
    assert.equal(s.beta.verdict, "GO");
    assert.equal(s.public.verdict, "GO");
  });
  it("subscription login: a beta warning but a public blocker, with the exact fix", async () => {
    const m = await mod(); const f = healthy(); (f.svc as { auth: string }).auth = "subscription";
    const r = byId(m.evaluate(f), "svc-auth");
    assert.equal(r.beta, "WARN"); assert.equal(r.public, "FAIL");
    assert.match(r.action, /API_KEY=/);
  });
  it("a split launch pair is a blocker for both audiences; public without an API key too", async () => {
    const m = await mod(); const f = healthy();
    f.settings = { cyrus_studio_public_enabled: "true", cyrus_tok_live: "false" };
    const rows = m.evaluate(f);
    assert.equal(byId(rows, "pair").beta, "FAIL");
    const g = healthy(); g.settings = { cyrus_studio_public_enabled: "true", cyrus_tok_live: "true" }; (g.svc as { auth: string }).auth = "subscription";
    assert.equal(byId(m.evaluate(g), "pair-auth").beta, "FAIL");
  });
  it("tokens live with enforcement off is a blocker", async () => {
    const m = await mod(); const f = healthy();
    f.settings = { cyrus_studio_public_enabled: "true", cyrus_tok_live: "true", cyrus_tok_enforce: "false" };
    assert.equal(byId(m.evaluate(f), "tok-enforce").public, "FAIL");
  });
  it("placeholder defaults only block a public launch (marked decided once a value is stored)", async () => {
    const m = await mod(); const f = healthy();
    let r = byId(m.evaluate(f), "placeholders");
    assert.equal(r.beta, "INFO"); assert.equal(r.public, "WARN");
    (f.settings as Record<string, string>).cyrus_tok_plan_free_games = "1";
    r = byId(m.evaluate(f), "placeholders");
    assert.equal(r.public, "PASS");
  });
  it("Stripe test mode and missing webhook secret fail the public launch only", async () => {
    const m = await mod(); const f = healthy(); f.stripe = { keyMode: "test", webhookSecretSet: false, webhookStatus: 404 };
    const rows = m.evaluate(f);
    assert.equal(byId(rows, "stripe-mode").public, "FAIL"); assert.equal(byId(rows, "stripe-mode").beta, "WARN");
    assert.equal(byId(rows, "stripe-webhook").public, "FAIL");
  });
  it("sound library cleared without a ledger is a blocker; with undecided rows a warning", async () => {
    const m = await mod(); const f = healthy(); f.env = { CYRUS_SOUND_LIBRARY_CLEARED: "1" }; f.ledger = { exists: false };
    assert.equal(byId(m.evaluate(f), "licence").beta, "FAIL");
    f.ledger = { exists: true, rows: 3, included: 2, decisions: { INCLUDED: 2, PENDING: 1 } };
    assert.equal(byId(m.evaluate(f), "licence").beta, "WARN");
  });
  it("certificates: warn under 21 days, fail under 7, fail when unreadable", async () => {
    const m = await mod(); const f = healthy();
    const st = (d: number | null) => { f.tls = { x: { label: "x", daysLeft: d, error: "no route" } }; return byId(m.evaluate(f), "tls-x").beta; };
    assert.equal(st(30), "PASS"); assert.equal(st(10), "WARN"); assert.equal(st(3), "FAIL"); assert.equal(st(null), "FAIL");
  });
  it("disks and backups use the thresholds; a missing off-box copy is a public blocker only", async () => {
    const m = await mod(); const f = healthy();
    (f.disks as Record<string, { pct: number }>).root.pct = 91;
    assert.equal(byId(m.evaluate(f), "disk-root").beta, "FAIL");
    (f.backup as Record<string, unknown>).lastSuccess = hoursAgo(40);
    (f.backup as Record<string, unknown>).offboxLastSuccess = null;
    const rows = m.evaluate(f);
    assert.equal(byId(rows, "backup-fresh").beta, "WARN");
    assert.equal(byId(rows, "backup-offbox").beta, "WARN"); assert.equal(byId(rows, "backup-offbox").public, "FAIL");
    (f.backup as Record<string, unknown>).lastSuccess = null;
    assert.equal(byId(m.evaluate(f), "backup-fresh").beta, "FAIL");
  });
  it("nginx: missing proxy prefixes are named; the error endpoint and legal links are reported", async () => {
    const m = await mod(); const f = healthy();
    (f.nginx as { appPrefixes: string[] }).appPrefixes = ["studio", "sign-in"];
    f.errlog = { status: 404 }; f.legal = { pages: { terms: 200, privacy: 404, aup: 200 }, signupLinks: false, footerLinks: true };
    const rows = m.evaluate(f);
    assert.match(byId(rows, "nginx-paths").beta === "WARN" ? "x" : "y", /x/);
    assert.equal(byId(rows, "errlog").beta, "FAIL");
    assert.equal(byId(rows, "legal-pages").beta, "FAIL");
    assert.equal(byId(rows, "legal-linked").public, "FAIL"); assert.equal(byId(rows, "legal-linked").beta, "WARN");
  });
  it("eval verdict: old, low or missing runs are flagged", async () => {
    const m = await mod(); const f = healthy();
    (f.eval as Record<string, unknown>).at = hoursAgo(24 * 40);
    assert.equal(byId(m.evaluate(f), "eval").public, "FAIL");
    f.eval = { at: hoursAgo(1), verdict: "pass", finalPassPct: 70, passAt1Pct: 50, baselineExists: true };
    assert.equal(byId(m.evaluate(f), "eval").public, "FAIL");
    f.eval = { at: null, baselineExists: false };
    assert.equal(byId(m.evaluate(f), "eval").beta, "WARN");
  });
  it("unreachable service and unreadable settings fail; the table lists blockers and exit logic follows the audience", async () => {
    const m = await mod(); const f = healthy(); f.svc = null; f.settings = null;
    const res = m.buildResult(f);
    const t = m.renderTable(res, "public");
    assert.match(t, /private beta : NO-GO/); assert.match(t, /svc-reachable/);
    assert.ok(!/sk_live|postgres:\/\//.test(t));
  });
});

describe("launch-eval: parsers", () => {
  it("parseCsv handles quotes, commas and doubled quotes; ledgerFacts counts decisions", async () => {
    const m = await mod();
    const csv = 'source,pack,licence_quoted,decision\nkay,"a,b","say ""hi""",INCLUDED\nx,y,z,EXCLUDED\nq,r,s,PENDING\n';
    assert.deepEqual(m.parseCsv(csv)[1], ["kay", "a,b", 'say "hi"', "INCLUDED"]);
    assert.deepEqual(m.ledgerFacts(csv), { exists: true, rows: 3, included: 1, decisions: { INCLUDED: 1, EXCLUDED: 1, PENDING: 1 } });
  });
  it("nginxAppPrefixes reads the production location regexes; stripeKeyMode never needs the key printed", async () => {
    const m = await mod();
    const conf = readFileSync("/etc/nginx/sites-enabled/cyrus-my", "utf8").length ? 'location ~ ^/(sign-in|auth)(/|$) {}\n location ~ ^/(studio|api/cyrus|_next)(/|$) {}' : "";
    assert.deepEqual(m.nginxAppPrefixes(conf), ["sign-in", "auth", "studio", "api/cyrus", "_next"]);
    assert.equal(m.stripeKeyMode("sk_live_abc"), "live"); assert.equal(m.stripeKeyMode("sk_test_abc"), "test"); assert.equal(m.stripeKeyMode(""), "none");
  });
  it("parseLaunchCheck round-trips the script's JSON and rejects anything else", async () => {
    const m = await mod();
    const res = m.buildResult(healthy());
    const p = parseLaunchCheck(JSON.parse(JSON.stringify(res)), "x");
    assert.ok(p && p.rows.length === res.rows.length);
    assert.equal(p!.beta.verdict, (res.summary as { beta: { verdict: string } }).beta.verdict);
    assert.equal(parseLaunchCheck({ schema: "nope", rows: [] }), null);
    assert.equal(parseLaunchCheck(null), null);
  });
});

describe("launch-check drift guards", () => {
  it("placeholder-keys.json is exactly the catalog's PLACEHOLDER-marked settings", () => {
    const want = CYRUS_SETTINGS.filter((s) => /PLACEHOLDER/.test(s.description)).map((s) => s.key).sort();
    const have = JSON.parse(readFileSync(path.join(ROOT, "scripts/cyrus/lib/placeholder-keys.json"), "utf8"));
    assert.deepEqual(have, want);
  });
  it("every first segment the Cyrus host routes to the app is in REQUIRED_APP_PREFIXES, and each prefix routes", async () => {
    const m = await mod();
    const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", CYRUS_HOSTS: "cyrus.my", APP_URL: "https://nxeon.cloud" });
    for (const p of Object.keys(CYRUS_APP_PATHS)) assert.ok(m.REQUIRED_APP_PREFIXES.includes(p.slice(1)), `${p} missing`);
    for (const pre of m.REQUIRED_APP_PREFIXES) {
      const r = cyrusHostRoute({ pathname: `/${pre}`, search: "", method: "GET", cfg });
      assert.notEqual(r.kind, "notfound", `/${pre} would 404 on the Cyrus host`);
    }
  });
});
