  it("thresholds: stored settings override defaults; garbage falls back", async () => {
    const m = await mod();
    const t = m.thresholds({ cyrus_alert_queue_depth: "5", cyrus_alert_cert_days: "abc" });
    assert.equal(t.cyrus_alert_queue_depth, 5);
    assert.equal(t.cyrus_alert_cert_days, m.ALERT_DEFAULTS.cyrus_alert_cert_days);
  });
  it("queue depth and wait", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.queueProblem({ depth: 3, oldestWaitMin: 2 }, t), "");
    assert.match(m.queueProblem({ depth: 25, oldestWaitMin: 2 }, t), /25 builds queued/);
    assert.match(m.queueProblem({ depth: 3, oldestWaitMin: 40 }, t), /waited 40 min/);
  });
  it("build failure rate needs a minimum sample", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.failureRateProblem({ finished: 4, failed: 4 }, t), "");
    assert.equal(m.failureRateProblem({ finished: 10, failed: 5 }, t), "");
    assert.match(m.failureRateProblem({ finished: 10, failed: 6 }, t), /6\/10/);
  });
  it("ai_unavailable and session-limit bursts add up", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.aiBurstProblem({ ai_unavailable: 2, session_limit: 2 }, t), "");
    assert.match(m.aiBurstProblem({ ai_unavailable: 3, session_limit: 2 }, t), /5 AI backend failures/);
  });
  it("certificate expiry under 14 days, or unreadable", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.certProblem({ host: "h", daysLeft: 30 }, t), "");
    assert.match(m.certProblem({ host: "h", daysLeft: 13 }, t), /13 days/);
    assert.match(m.certProblem({ host: "h", daysLeft: null, error: "timeout" }, t), /no certificate/);
  });
  it("token ledger anomalies", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.ledgerProblem({ mismatched: 0, negative: 0, staleReservations: 0 }, t), "");
    const p = m.ledgerProblem({ mismatched: 2, negative: 1, staleReservations: 3 }, t);
    assert.match(p, /differs from the ledger/); assert.match(p, /negative/); assert.match(p, /reservation/);
    assert.equal(m.ledgerProblem({ mismatched: 2, negative: 0, staleReservations: 0 }, m.thresholds({ cyrus_alert_ledger_mismatch: "5" })), "");
  });
  it("error rate and webhook failures", async () => {
    const m = await mod(); const t = m.thresholds();
    assert.equal(m.errorRateProblem({ occurrences10m: 30, top: "x" }, t), "");
    assert.match(m.errorRateProblem({ occurrences10m: 31, top: "checkout" }, t), /checkout/);
    assert.equal(m.webhookProblem({ dead: 1, failed24h: 1 }, t), "");
    assert.match(m.webhookProblem({ dead: 1, failed24h: 2 }, t), /3 webhook failures/);
  });
  it("public status JSON carries component states only", async () => {
    const m = await mod();
    const s = m.publicStatus([{ id: "build-queue-stuck", firing: true, severity: "warning" }, { id: "health-down", firing: false, severity: "critical" }], "2026-10-14T00:00:00Z");
    assert.equal(s.status, "degraded");
    assert.equal(s.components.find((c: { id: string }) => c.id === "builds").status, "degraded");
    assert.equal(s.components.find((c: { id: string }) => c.id === "studio").status, "operational");
    assert.ok(!JSON.stringify(s).includes("queued"));
    const o = m.publicStatus([{ id: "health-down", firing: true, severity: "critical" }], "x");
    assert.equal(o.status, "outage");
  });
  it("every cyrus_alert_* default is a catalog setting with the same default and a PLACEHOLDER marker", async () => {
    const m = await mod();
    for (const [k, d] of Object.entries(m.ALERT_DEFAULTS)) {
      const def = CYRUS_SETTINGS.find((s) => s.key === k);
      assert.ok(def, k); assert.equal(def!.default, String(d), k); assert.match(def!.description, /PLACEHOLDER/);
    }
  });
  it("alert-rules.json: every signal/cert rule names a known evaluator and the status components reference real rule ids", async () => {
    const m = await mod();
    const rules = JSON.parse(readFileSync(path.join(ROOT, "deploy/cyrus/alert-rules.json"), "utf8")).rules as { id: string; kind: string; signal?: string }[];
    for (const r of rules.filter((x) => x.kind === "signal" || x.kind === "cert")) assert.ok(r.signal && typeof m.SIGNALS[r.signal] === "function", r.id);
    const ids = new Set(rules.map((r) => r.id));
    for (const c of m.STATUS_COMPONENTS) for (const id of c.rules) assert.ok(ids.has(id), `${c.id}: ${id}`);
  });
});
